/**
 * Invite friends: the account's link, kept in meta `invite` so Settings and
 * Today draw from local data, and the one card on Today that offers it after
 * a good moment (owner, 2026-10-12: "offered once after a good moment …
 * never as a modal, at most once per 30 days"). Every threshold is a named
 * constant here with a test.
 */
import { me } from '@/api/endpoints.js';
import type { ApiReferralVia, ApiReferralView } from '@/api/types.js';
import { db, getMeta, type StoredInvite } from '@/db/schema.js';
import { platform } from '@/lib/platform/index.js';

/** The good moments, by celebration key: the first mastered word, and a 7-day streak. */
export const FIRST_MASTERED_KEY = 'first-mastered';
const STREAK_SEVEN = /^streak:\d+:7$/;

/**
 * How many days after a good moment Today may still offer the card. A
 * moment from last week is still fresh; one from last month is not why
 * anybody would share the app today.
 */
export const INVITE_MOMENT_DAYS = 7;

/** At most one offer in this many days on a device. */
export const INVITE_EVERY_DAYS = 30;

const DAY_MS = 24 * 60 * 60 * 1000;

const EMPTY: StoredInvite = { view: null, at: null, momentDay: null, shownAt: null };

/** Whether a celebration key is one of the good moments. */
export function isGoodMoment(key: string): boolean {
  return key === FIRST_MASTERED_KEY || STREAK_SEVEN.test(key);
}

async function change(edit: (state: StoredInvite) => StoredInvite): Promise<StoredInvite> {
  return db.transaction('rw', db.meta, async () => {
    const next = edit((await getMeta('invite')) ?? EMPTY);
    await db.meta.put({ key: 'invite', value: next });
    return next;
  });
}

/** The stored invitation, read again from the server. Throws when it cannot be read. */
export async function refreshInvite(via?: ApiReferralVia, now: Date = new Date()): Promise<ApiReferralView> {
  const view = await me.referral(via);
  await change((state) => ({ ...state, view, at: now.toISOString() }));
  return view;
}

/**
 * Notes that a good moment was shown on this device today, and reads the
 * link once so Today can tell whether the programme is on. Never throws:
 * a celebration must not fail because of this.
 */
export async function noteGoodMoment(key: string, today: number): Promise<void> {
  if (!isGoodMoment(key)) return;
  try {
    await change((state) => ({ ...state, momentDay: today }));
    if (platform.network.online) await refreshInvite();
  } catch {
    /* the card simply does not come */
  }
}

/**
 * Whether Today offers the card now: the programme on (as last read), a
 * good moment on an earlier day within INVITE_MOMENT_DAYS (never beside the
 * celebration itself), and no offer in the last INVITE_EVERY_DAYS.
 */
export function inviteOffered(state: StoredInvite | null, today: number, now: number): boolean {
  if (state?.view?.enabled !== true || state.momentDay === null) return false;
  const since = today - state.momentDay;
  if (since < 1 || since > INVITE_MOMENT_DAYS) return false;
  return state.shownAt === null || now - state.shownAt >= INVITE_EVERY_DAYS * DAY_MS;
}

/** The card was on screen: it is not offered again for INVITE_EVERY_DAYS, and this moment is spent. */
export async function markInviteShown(now: number = Date.now()): Promise<void> {
  await change((state) => ({ ...state, shownAt: now, momentDay: null }));
}

/**
 * The good moment many more learners reach than a 7-day streak (growth
 * study 2026-10-13, an estimate to tune): this many words of their own,
 * with practice on WORDS_MOMENT_DAYS different days.
 */
export const WORDS_MOMENT_WORDS = 25;
export const WORDS_MOMENT_DAYS = 3;

/** Whether the words moment has been reached. */
export function wordsMomentReached(words: number, practiceDays: number): boolean {
  return words >= WORDS_MOMENT_WORDS && practiceDays >= WORDS_MOMENT_DAYS;
}

/**
 * Notes the words moment the first time Today sees it reached on this
 * device (it is noted once, ever), so the card may come on a later day,
 * under the same 30-day cap. Never throws.
 */
export async function noteWordsMoment(today: number): Promise<void> {
  try {
    const before = await getMeta('invite');
    if (before?.wordsMoment === true) return;
    await change((state) => ({ ...state, wordsMoment: true, momentDay: state.momentDay ?? today }));
    if (platform.network.online && before?.view == null) await refreshInvite();
  } catch {
    /* the card simply does not come */
  }
}
